    def all_cdn_log_subscriptions(
        self, service_name: str, *, kind: str | None | NotGiven = NOT_GIVEN
    ) -> t.AsyncIterator[models.DbaasLogsLogSubscription]:
        """all_cdn_log_subscriptions iterates over GET /v1/hosting/web/{serviceName}/cdn/log/subscription (List log subscriptions).

        It lists the IDs with list_cdn_log_subscriptions, then gets each object with get_cdn_log_subscription,
        only when the loop reaches it. An object deleted in the meantime is skipped. Any other
        error is raised and stops the loop. Use it with ``async for``.

        Args:
            service_name: Service name
            kind: Filter on a specific kind (e.g., audit) (optional)

        The two calls require the IAM action webHosting:apiovh:cdn/log/subscription/get.
        """
        return self._each(
            lambda: self.list_cdn_log_subscriptions(
                service_name,
                kind=kind,
            ),
            lambda listed_id: self.get_cdn_log_subscription(service_name, listed_id),
        )

